def _validate_start_date(self, start_date: str, schedule_expression: str) -> None:
    """
    Validate that the StartDate is not more than 5 minutes in the past
    for schedules with recurrence expressions (containing '*').
    """
    if start_date and '*' in schedule_expression:
        # Convert start_date to timestamp if it's not already
        if isinstance(start_date, str) and start_date.isdigit():
            start_date_timestamp = int(start_date)
        else:
            start_date_timestamp = int(start_date)

        # Get current time and calculate 5 minutes ago
        current_time = time.time()
        five_minutes_ago = current_time - (5 * 60)

        # Check if start_date is more than 5 minutes in the past
        if start_date_timestamp < five_minutes_ago:
            raise JsonRESTError(
                "ValidationException",
                "The StartDate you specify cannot be earlier than 5 minutes ago."
            )

